    no3mfBanner: {
      title: 'Niektórych ostatnich wydruków nie udało się zarchiwizować z miniaturami',
      body: 'Slicer nie zostawił pliku .gcode.3mf na karcie SD drukarki, więc Bambuddy nie mógł pobrać miniatury ani metadanych slicera. Zwykle dzieje się tak, gdy w slicerze wyłączona jest opcja "Store sent files on external storage" (karta Device w Bambu Studio / OrcaSlicer).',
      docsLink: 'Zobacz krok 4 instalacji',
      dismissLabel: 'Zamknij to powiadomienie',
      docsLinkInternalStorage: 'Dlaczego tak się dzieje',
      titleInternalStorage: 'Niektóre ostatnie wydruki zostały w pamięci wewnętrznej drukarki',
      bodyInternalStorage: 'Bambu Studio zapisał pocięty plik w pamięci wewnętrznej drukarki zamiast na karcie, więc Bambuddy nie miał czego odczytać przez FTP. W seriach H2, P2S i X2D przycisk Print zawsze tak robi — wybór daje tylko Send, a i tam domyślnie ustawione jest Cache. Te wydruki są nadal archiwizowane z nazwą i czasem, tylko bez miniatury i metadanych slicera. Aby uzyskać pełne archiwa, uruchom wydruk z Bambuddy albo tnij w OrcaSlicer — lub w Bambu Studio użyj Send z wybraną opcją External i uruchom wydruk później. Wszystkie te sposoby wymagają karty lub pendrive\'a w drukarce.',
      titleNoExternalStorage: 'Niektórych ostatnich wydruków nie udało się zarchiwizować — brak nośnika w drukarce',
      bodyNoExternalStorage: 'Drukarka zgłasza brak karty lub pendrive\'a w gnieździe, więc pocięty plik nie miał gdzie trafić, a Bambuddy nie miał czego odczytać. Włóż nośnik, a następny wydruk zostanie zarchiwizowany w całości.',
      titleInternalHistory: 'Niektóre ostatnie wydruki uruchomiono z pliku, który był już na drukarce',
      bodyInternalHistory: 'Te wydruki uruchomiono z własnej biblioteki drukarki — ponowny wydruk z jej ekranu, start z Handy lub plik wysłany wcześniej i wydrukowany później. Bambuddy odczytuje pliki wydruku przez FTP, który udostępnia tylko kartę lub pendrive, a drukarka trzyma tę bibliotekę w obszarze niedostępnym dla FTP, więc nie było pliku 3MF do odczytania. Żadne ustawienie slicera tego nie zmieni, bo dla tych wydruków nic nie zostało wysłane. Są one nadal archiwizowane z nazwą i czasem, a w Edytuj archiwum możesz ręcznie uzupełnić zużyty filament. Aby uzyskać pełne archiwum, uruchom wydruk z Bambuddy lub ze slicera.',
      titleFtpsCooloff: 'Niektórych ostatnich wydruków nie udało się zarchiwizować — drukarka odrzuciła połączenie do przesyłu plików',
      bodyFtpsCooloff: 'Bambuddy otworzył port przesyłu plików drukarki (FTPS 990), a drukarka odpowiedziała czymś, co nie jest TLS, więc nie dało się nic z niej odczytać. Te wydruki są nadal archiwizowane z nazwą i czasem, tylko bez miniatury i metadanych slicera. To nie jest ustawienie slicera ani nic, co zmieniłeś — te same modele i firmware działają normalnie w innych instalacjach, a dotknięta drukarka zwykle po pewnym czasie sama zaczyna znowu działać. Po takim błędzie Bambuddy wstrzymuje przesyły do tej drukarki na pięć minut i wraca po plik, gdy przerwa minie, więc krótki epizod uzupełnia się sam; karta nadal pusta oznacza, że odmowa trwała dłużej niż ponowna próba. Przyczyna nie jest jeszcze znana. Jeśli problem się powtarza, włącz logowanie debugowania na stronie System i dołącz pakiet wsparcia do zgłoszenia.',
      titleFtpTransferFailed: 'Niektórych ostatnich wydruków nie udało się zarchiwizować — przesył pliku przekroczył limit czasu',
      bodyFtpTransferFailed: 'Pocięty plik był na karcie drukarki i drukarka go udostępniła, ale przesył nie zakończył się w dozwolonym czasie. Na początku wydruku drukarka obsługuje też kamerę, komunikaty stanu i przesyłanie zadania, a duży plik 3MF nie zawsze przechodzi przy tym wszystkim. Te wydruki są nadal archiwizowane z nazwą i czasem, tylko bez miniatury i metadanych slicera. To nie jest ustawienie slicera ani nic, co zmieniłeś. Bambuddy wraca po plik trzy razy w ciągu kolejnych dziesięciu minut, więc większość z nich uzupełnia się sama; karta nadal pusta oznacza, że każda próba również przekroczyła limit czasu. Jeśli problem się powtarza, zwiększ Connection Timeout w Ustawienia > Sieć > FTP Retry.',
    },
