    confirmDefaultGoodOnPlateClearDescription: 'Gdy płyta zostanie zwolniona (ręcznie lub przez następny wydruk z kolejki), a pytanie o wynik wydruku nadal nie ma odpowiedzi, automatycznie zapisz go jako dobrą część. Wydruk liczy się wtedy jako dobry od razu po zwolnieniu płyty; późniejsza odpowiedź przez Telegram lub link pokazuje już tylko zapisany wynik.',
