    concurrentUploadsTitle: 'Równoczesne przesyłanie',
    concurrentUploadsDescription: 'Do ilu drukarek kolejka może jednocześnie wysyłać pliki. Drukarki odbierają pliki powoli (duży wydruk może trwać kilka minut), a każda czeka na swoją kolej — dlatego przy większej flocie zwiększenie tej wartości sprawia, że ostatnia drukarka w partii nie czeka na zakończenie wszystkich wcześniejszych transferów. Zmniejsz ją, jeśli sieć lub host Bambuddy nie radzi sobie z równoległymi transferami.',
    concurrentUploadsLabel: 'Liczba drukarek jednocześnie',
