    staggeredStart: 'Start rozłożony w czasie',
    staggeredStartDescription: 'Domyślna wielkość grupy i odstęp przy rozkładaniu w czasie startu partii na wielu drukarkach. Można je zmienić dla każdej partii w oknie druku.',
    preheatTitle: 'Podgrzewanie i wygrzewanie',
    preheatDescription: 'Podgrzej stół (i komorę, jeśli jest obsługiwana) i utrzymaj temperaturę przed startem każdego wydruku z kolejki. Pomocne przy filamentach technicznych (PA, ABS) na drukarkach bez aktywnego grzania komory — stół ogrzewa komorę przez promieniowanie, gdy odlicza się czas wygrzewania. Temperatura docelowa stołu jest odczytywana z pliku wydruku; zachowanie komory zależy od modelu drukarki.',
    preheatEnabled: 'Włącz podgrzewanie i wygrzewanie',
    preheatEnabledDesc: 'Po wyłączeniu wydruki z kolejki są wysyłane natychmiast. Każdy element kolejki może to zmienić dla danego wydruku.',
    preheatFilamentTargetsLabel: 'Docelowa temperatura komory dla filamentu (°C)',
    preheatFilamentTargetsHint: 'Bambuddy wybiera najwyższą wartość docelową spośród załadowanych slotów AMS. Wydruk, którego wszystkie sloty dają 0 — PLA, PETG, TPU, PVA — całkowicie pomija podgrzewanie i startuje natychmiast.',
    preheatFilamentTargetsReset: 'Przywróć domyślne',
    preheatFilamentTargetsDefaultRow: 'Inne / niezmapowane',
