    plateClear: 'Potwierdzenie opróżnienia płyty',
    requirePlateClear: 'Wymagaj potwierdzenia opróżnienia płyty',
    requirePlateClearDescription: 'Po włączeniu harmonogram czeka na potwierdzenie opróżnienia płyty dla danej drukarki, zanim uruchomi wydruki z kolejki na drukarkach z ukończonymi zadaniami. Wyłączenie ukrywa też plakietkę stanu płyty i przycisk „Oznacz płytę jako opróżnioną” na kartach drukarek.',
    keepBedWarm: 'Utrzymuj ciepły stół między wydrukami',
    keepBedWarmDesc: 'Podczas oczekiwania na opróżnienie płyty utrzymuj stół w podanej poniżej temperaturze podtrzymania, aby komora pozostała gorąca — lub w temperaturze stołu następnego wydruku, jeśli jest wyższa. Dotyczy tylko sytuacji, gdy następny wydruk wymaga ogrzewania komory (ASA, ABS, PA, PC itp.). Wymaga włączonego potwierdzenia opróżnienia płyty.',
    keepWarmBedTemp: 'Temperatura podtrzymania stołu (°C)',
    keepWarmBedTempHelp: 'Używana zawsze, gdy zadaniem stołu jest ogrzewanie komory — przy podtrzymaniu ciepła oraz przy podgrzewaniu, gdy plik wydruku nie zawiera temperatury stołu. Wyższa temperatura stołu z pliku wydruku zawsze ma pierwszeństwo.',
    keepWarmMaxMinutes: 'Przestań podtrzymywać ciepło po (minuty)',
