    orcaslicerKnownIssuesWarning: 'OrcaSlicer 2.3.2 / 2.4.0-dev mają znane błędy CLI, które blokują slicowanie wielu plików 3MF utworzonych przez Bambu — zobacz zgłoszenia upstream #12426 (segfault na malowanych plikach z wieloma ekstruderami) i #13386 (odrzucenie przez ścisłą walidację zakresu parametrów). Do czasu wprowadzenia poprawek upstream zalecane jest Bambu Studio.',
